3	import Handlebars from 'handlebars';
4	
5	export const DEFAULT_TEMPLATE_NAME = 'page';
6	export const DEFAULT_LAYOUT_NAME = 'default';
7	export const INDEX_TEMPLATE_NAME = 'index';
8	
9	const FALLBACK_LAYOUT = `<!DOCTYPE html>
10	<html lang="en">
11	<head>
12	<meta charset="UTF-8">
13	<title>{{title}}</title>
14	</head>
15	<body>
16	{{{body}}}
17	</body>
18	</html>
19	`;
20	
21	const FALLBACK_PAGE_TEMPLATE = `<a href="index.html">&larr; Back to index</a>
22	<h1>{{title}}</h1>
23	{{#if date}}<p class="date">{{date}}</p>{{/if}}
24	{{#if tags.length}}<ul class="tags">{{#each tags}}<li>{{this}}</li>{{/each}}</ul>{{/if}}
25	<article>
26	{{{html}}}
27	</article>
28	`;
29	
30	const FALLBACK_INDEX_TEMPLATE = `<h1>Index</h1>
31	<ul class="pages">
32	{{#each pages}}
33	<li><a href="{{outputPath}}">{{title}}</a>{{#if date}} <span class="date">{{date}}</span>{{/if}}</li>
34	{{/each}}
35	</ul>
36	`;
37	
38	function readIfExists(filePath: string): string | null {
39	  return fs.existsSync(filePath) ? fs.readFileSync(filePath, 'utf-8') : null;
40	}
41	
42	/**
43	 * Renders page content into a named template, then wraps the result in a
44	 * named layout via the layout's `{{{body}}}` placeholder. Templates and
45	 * layouts are read from disk on each render so authors can edit .hbs files
46	 * without restarting the build; falls back to built-in defaults whenever a
47	 * requested (or missing) template/layout file isn't present on disk, so a
48	 * project without a ./templates directory still builds.
49	 */
50	export class TemplateEngine {
51	  private readonly handlebars: typeof Handlebars;
52	
53	  private readonly templatesDir: string;
54	
55	  constructor(templatesDir: string) {
56	    this.templatesDir = templatesDir;
57	    this.handlebars = Handlebars.create();
58	    this.registerPartials();
59	  }
60	
61	  private registerPartials(): void {
62	    const partialsDir = path.join(this.templatesDir, 'partials');
63	    if (!fs.existsSync(partialsDir)) return;
64	
65	    const entries = fs.readdirSync(partialsDir).filter((name) => /\.hbs$/i.test(name));
66	    for (const entry of entries) {
67	      const name = entry.replace(/\.hbs$/i, '');
68	      const source = fs.readFileSync(path.join(partialsDir, entry), 'utf-8');
69	      this.handlebars.registerPartial(name, source);
70	    }
71	  }
72	
73	  private fallbackFor(templateName: string): string {
74	    return templateName === INDEX_TEMPLATE_NAME ? FALLBACK_INDEX_TEMPLATE : FALLBACK_PAGE_TEMPLATE;
75	  }
76	
77	  renderTemplate(templateName: string, context: Record<string, unknown>): string {
78	    const filePath = path.join(this.templatesDir, `${templateName}.hbs`);
79	    const source = readIfExists(filePath) ?? this.fallbackFor(templateName);
80	    return this.handlebars.compile(source)(context);
81	  }
82	
83	  renderLayout(layoutName: string, context: Record<string, unknown>): string {
84	    const filePath = path.join(this.templatesDir, 'layouts', `${layoutName}.hbs`);
85	    const source = readIfExists(filePath) ?? FALLBACK_LAYOUT;
86	    return this.handlebars.compile(source)(context);
87	  }
88	
89	  render(templateName: string, layoutName: string, context: Record<string, unknown>): string {
90	    const body = this.renderTemplate(templateName, context);
91	    return this.renderLayout(layoutName, { ...context, body });
92	  }
93	}
